/// @sort 3
uniform float First = 1.0;
/// @sort 32
uniform float Second = 2.0;
// One property with an explicit sort and one without: the one without gets 1.x's 32, recorded as synthesized.
/// @name M_LpSort
export void M_LpSort(inout material Base)
{
    float Value = 0;
    Value = First + Second;
    Base.Opacity = Value;
}
